import{_ as a,o as t,c as n,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"From Pixels to States: Rethinking Interactive World Models as Game Engines","description":"","frontmatter":{"title":"From Pixels to States: Rethinking Interactive World Models as Game Engines","arxiv":"2607.14076","date":"2026-07-15","authors":"Zhen Li, Zian Meng, Shuwei Shi, Mingliang Zhai, Jiaming Tan, Chuanhao Li, Kaipeng Zhang","categories":"cs.CV","topics":"世界模型, 交互式游戏世界, 游戏状态","outline":[2,2]},"headers":[],"relativePath":"papers/2607.14076.md","filePath":"papers/2607.14076.md","lastUpdated":null}'),p={name:"papers/2607.14076.md"};function l(i,s,r,o,m,c){return t(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="from-pixels-to-states-rethinking-interactive-world-models-as-game-engines" tabindex="-1">From Pixels to States: Rethinking Interactive World Models as Game Engines <a class="header-anchor" href="#from-pixels-to-states-rethinking-interactive-world-models-as-game-engines" aria-label="Permalink to &quot;From Pixels to States: Rethinking Interactive World Models as Game Engines&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.14076" target="_blank" rel="noreferrer">2607.14076</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-15</td></tr><tr><td><strong>作者</strong></td><td>Zhen Li, Zian Meng, Shuwei Shi, Mingliang Zhai, Jiaming Tan, Chuanhao Li, Kaipeng Zhang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用传统引擎的「动作—状态—观测」循环重新切分交互式世界模型，指出四个维度的瓶颈全都指向被大多数模型隐式化的 game state，并放出 90 小时《黑神话：悟空》带引擎真值状态的数据集。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型正在被当作下一代游戏引擎来讨论。给定玩家按键，模型直接预测下一批画面，不再需要手工搭几何、资产和行为规则。问题是&quot;能生成好看的可控视频&quot;和&quot;能当引擎用&quot;之间隔着三件具体的事：交互结果必须遵循随游戏条件演化的规则；后果必须在长时间跨度上持续存在；整个生成循环必须跑在玩家能忍受的延迟内。</p><p>论文的组织方式是把传统引擎的递归循环拿来当尺子。作者举的例子很具体：在《黑神话：悟空》里按下攻击键，引擎不会直接产生像素，它先查当前状态（耐力够不够、技能是否冷却、Boss 的位置和动画相位是否处于可破防阶段），再按战斗规则裁定结果（打空、造成伤害、打断动作、还是触发阶段转换），最后才从更新后的状态渲染帧。沿这条循环，作者把交互式游戏世界建模拆成四个维度：<strong>player action control</strong>（玩家意图如何表示）、<strong>game state dynamics</strong>（世界内部条件如何表示与演化）、<strong>state-observation persistence</strong>（后果能否跨越视野与时间保持一致）、<strong>real-time interactive generation</strong>（能否在游玩延迟内交付）。</p><p>这个切法有价值，是因为现有研究线（相机控制、语言事件控制、记忆机制、蒸馏加速）各自推进，彼此的连接和合起来离&quot;可玩世界&quot;还差什么，一直没人讲清楚。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文对每个维度都点名了具体的方法族。</p><p>动作表示上，几何轨迹一路（MotionCtrl 的旋转平移编码、CameraCtrl 的 Plücker 射线嵌入、CamCo/CamI2V 的极线约束注意力）能给出精确一致的视点控制，但只覆盖导航，而且要求的精确轨迹离玩家真实输入很远。运动信号一路（Oasis 与 Matrix-Game 系列把逐帧键鼠状态编成条件向量、MineWorld 与 iVideoGPT 把动作交织成 token、Hunyuan-GameCraft 把离散按键映射成连续相机表示、SCOPE 把开火这类局部事件限制在受影响区域、Genie 系列从无标注视频学 latent action）忠实于玩家的操作方式，但原始信号欠定意图：同一个按键在不同游戏状态下含义不同，连招这类复合操作的语义超出单次按键，很难学。语义事件一路（GameGen、Genie 3、Yume-1.5 的文本世界事件，Promptable Game Models 的逐 agent 语言动作，Incantation 的逐实体条件，ReactiveGWM 的 NPC 策略控制，ActWorld 的物体级交互）能表达任何固定输入方案覆盖不到的交互，代价是条件化开销随 grounding 粒度上升。</p><p>状态维度是全文的重心。主流做法是根本不维护独立状态，世界动力学完全活在像素里，从 Atari 上的动作条件预测到 GameNGen、DIAMOND、WHAM 再到键鼠驱动的开放式模型。这继承了视频基础模型的全部视觉能力，但状态只等于&quot;最近若干帧观测&quot;，规则被当成像素相关性来学，空间与逻辑一致性没有保证。第二类把状态压成 latent（GameGAN、Dreamer 系、以及把交互历史做成 state-space 摘要送进 diffusion 的近期工作），不需要游戏内标注因而好 scale，但不可解释，而且因为是从视觉预测学出来的，对&quot;非视觉原因导致的视觉变化&quot;不可靠——同一次攻击是击杀还是只造成伤害，取决于目标剩余血量，而血量不在画面里。第三类把状态写成符号或文本（WildWorld 的逐帧引擎内存状态标注、EgoCS-400K 的玩家状态事件对齐、AnimeGamer 的逐步属性预测），可读可验证，但需要大规模状态标注数据，而且 AnimeGamer 预测出来的状态并不真正驱动生成。</p><p>持久性维度上，作者把记忆机制按&quot;记录过去&quot;与&quot;估计当下&quot;分开。前者（时间索引的历史压缩、空间索引的 WorldMem / Context-as-Memory / VMem / RELIC）在静态场景里可靠，但交互世界一直在变，忠实复制的过去可能不是当下的正确参照——技能拆了一栋楼，回头看记忆却把完好的楼还回来。后者（ActWorld 的事件转移帧、Hybrid Memory 的视野外主体跟踪、flow-equivariant 的未观测区域动力学传播、PERSIST 的隐式 3D 状态推进）把更新交给模型自行判断，在各自领域有效，但游戏里高频交互带来的小变化会累积成大偏移，每一步都要做既高效又可靠的更新决策，缺乏原则性依据。</p><p>实时维度上，CausVid 系的少步蒸馏、Rolling Forcing 系的流式重构、minWM 与 InSpatio 的系统级优化都在缩短&quot;输入到下一帧&quot;的时间。作者在这里提出一个少见的区分：<strong>control latency</strong>（输入到可见响应，越小越好，决定手感）和 <strong>consequence latency</strong>（动作到规则裁定的后果，应该准确而不是越小越好，因为攻击有前摇、判定帧、后摇，结果瞬间出现反而是错的）。现有工作把所有延迟一律当成要缩小的量，没有机制去对齐后果出现的时刻。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个经验观察：这两年的交互世界模型演示都很像&quot;能走进去的视频&quot;，视点和位移控制得很好，但一旦涉及需要条件裁定的交互（攻击是否命中、技能是否可用），表现就不稳。同时另一条线索是，做游戏的人早就知道引擎不是渲染器，引擎的核心是那张显式的状态表和一套作用在它上面的规则，渲染只是最后一步。</p><p>把这两件事放在一起，一个自然的追问是：既然生成模型把整条循环压成了&quot;观测 → 观测&quot;，那么循环中间那一环去哪了？答案是它被吸收进了像素相关性。于是可以预测：所有依赖&quot;世界当前条件&quot;而非&quot;画面当前内容&quot;的能力，都会成为薄弱环节。作者随后逐维度检查现有方法族，发现三个仍然困难的能力——从累积条件裁定结果、把后果保持到视野之外、在规则定义的时刻交付效果——确实都绕回同一个缺失物。</p><p>第三步是数据。要学有规则的状态转移，需要游戏视频配上显式、逐帧对齐的状态标注，而现有数据集（GameGen 的、Sekai、GameFactory、PLAICraft、OmniWorld）都缺这一层，WildWorld 是少数例外。这解释了为什么显式状态路线只停留在&quot;数据与评测&quot;，没有进入生成循环。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>游戏引擎的循环是&quot;动作改状态、状态出画面&quot;，视频世界模型却把它压成了&quot;动作加历史帧出下一帧&quot;，中间那张显式状态表被丢掉了。凡是只能从状态而不能从画面读出来的东西——剩余血量、冷却、动画相位——决定的交互结果，模型就只能靠像素统计去猜。四个维度上剩下的硬骨头，本质上是同一根骨头：state 被隐式化了。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>这篇论文的方法贡献不是模型，而是一个可复用的数据引擎。作者选《黑神话：悟空》（Unreal Engine 的写实动作 RPG），聚焦 Boss 战，因为这类片段交互密集（攻击、闪避）、状态连续变化、单场持续数分钟，天然适合长时 rollout 的训练与评测。角色由技能水平和风格各异的众包玩家用原生键鼠操控。</p><p>采集阶段：给引擎打点，每个 tick 把动作与状态序列化成 JSON 写本地文件，因此每一帧都带完整交互上下文。观测侧用 ReShade 自定义 shader 把显示分成子窗口，同时呈现渲染缓冲里的 RGB 帧和深度图，并关闭 UI 的渲染 pass 得到干净画面；改造 OBS Studio 记录每帧的系统时间戳，与引擎侧同一时钟的记录一起提供帧级对齐的公共时间基准。为了统一异构众包机器，作者做了一套工具自动强制统一的游戏内设置与录制配置。</p><p>处理阶段：按时间戳逐帧对齐、按遭遇战切分、重编码；出现丢帧、卡顿或跨流不一致的样本整段丢弃。引擎导出的动作和状态是数值形式（动作 ID、世界坐标），精确但语义不透明，因此作者补两种 caption：<strong>slot caption</strong> 把固定长度时间窗内的逐 tick 记录聚合成结构化的动作槽与状态槽；<strong>semantic caption</strong> 由 Qwen3-VL-235B-A22B-Instruct 读采样帧加对应动作状态记录生成，描述执行了什么动作、状态如何转移。前者保精度，后者补语义，两者都可以用作语言式状态转移的监督或生成的状态条件。</p><p>最终数据集：90 小时以上，1280×720、30 FPS，三类帧对齐真值——玩家原始键鼠输入、状态（相机/角色/Boss 的位姿，当前动画、激活技能、血量耐力攻防装备等属性）、观测（RGB 与深度）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。为便于对照，可以把作者反复使用的引擎循环写成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，而主流视频世界模型学的是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，即把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 边缘化掉，只保留最近观测窗作为其代理。这两行式子是本文为帮助理解所加，不是论文原文写法。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>需要说清楚：这不是一篇有模型实验的论文，正文没有基线对比、没有消融、没有量化指标。它的&quot;实验&quot;部分是数据引擎本身与其规模统计。作者提出的问题是&quot;现有方法沿四个维度各自走到哪里&quot;，采用的方法是把方法归族后逐族分析强弱与权衡，得到的答案是：自然输入控制、可探索场景、接近实时的生成这三件事现有方法已经能交付；而依赖累积游戏条件裁定结果、把后果保持到当前视野之外、在规则定义的时刻呈现效果这三件事仍然困难，且都围绕被大多数模型隐式化的 game state。</p><p>由此产生的第二个问题是&quot;为什么显式状态路线推不动&quot;，作者的答案是数据缺口，并用数据引擎作答：证明在闭源 AAA 游戏上，用 ReShade + OBS + 引擎打点这套不需要额外硬件、对众包玩家开销很小的组合，可以低成本规模化拿到帧对齐的动作、状态、观测三元组。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：论文用传统引擎的动作—状态—观测循环作为统一视角，把交互式游戏世界建模切成动作控制、状态动力学、状态—观测持久性、实时生成四个维度。每个维度上现有方法被归成若干族并给出强弱与代价。结论是三项仍然困难的能力都绕回同一个缺失物：显式的 game state。作者进一步指出，显式状态路线之所以停留在数据与评测层面，是因为缺乏带引擎真值状态标注的游戏视频。为此他们放出《黑神话：悟空》90 小时、1280×720、30 FPS 的数据集，含帧对齐的键鼠输入、引擎导出状态、RGB 与深度，以及结构化槽位与语义两种 caption。</p><p><strong>3 句话版</strong>：视频世界模型把引擎循环压成了&quot;帧到帧&quot;，丢掉了中间的显式状态表。因此凡是由不可见状态决定的交互结果、跨视野的后果持久性、以及规则定义的后果出现时刻，都成为系统性弱项。论文沿四维度梳理了现状，并用一套众包数据引擎补上状态标注这块数据缺口。</p><p><strong>1 句话版</strong>：交互式世界模型真正缺的不是画质也不是速度，而是那张被隐式化的游戏状态表。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>把 game state 显式化并接入生成循环，是解决规则一致性的正确路线</strong>。整篇论文的组织逻辑、四维度的收敛点、以及数据集的设计动机全都压在这条判断上；如果它不成立，四维度的分析仍然有综述价值，但&quot;下一步该做什么&quot;的结论会整体失效。</p><p>它可能不成立的原因有二。其一，状态与观测并非正交：血量、耐力、冷却在真实游戏里通常就画在 HUD 上，一个不关 UI 的模型完全可以从画面读出这些量，此时显式状态只是被重新编码了一遍。作者恰恰在采集时禁用了 UI 渲染 pass 以获得&quot;干净帧&quot;，这个工程选择人为制造了部分可观测性，也就人为放大了显式状态的必要性。其二，历史上多次出现&quot;显式结构在小规模有效、被更大规模的端到端学习吃掉&quot;的模式，纯像素模型在足够数据与容量下是否会隐式学到规则，本文没有给出证据来排除。</p><p>论文为这条判断提供的证据是定性的：它引用了 kang2025how 这类关于像素相关性难以保证空间与逻辑一致性的观察，并指出 latent 状态对非视觉原因驱动的视觉变化不可靠。它没有提供的是一个受控实验，直接对比&quot;有显式状态条件&quot;与&quot;无显式状态条件&quot;的同一模型在规则依赖交互上的差距。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>目标是在一周内验证 §9 的那条核心判断，而不是复现整个数据引擎。</p><ul><li><strong>数据</strong>：不用 AAA 游戏。自建或改造一个 2D 战斗小 demo（例如给一个开源横版格斗加上打点），导出逐帧的按键、HP、耐力、冷却、动画相位与画面，并且<strong>关闭 HUD</strong>，保证状态不可从画面直接读出。采 5–10 小时即可。</li><li><strong>实现</strong>：同一个小型 latent video 模型训两个版本。A 版条件是 <code>(最近 k 帧, 当前按键)</code>；B 版额外拼上一个状态 token（HP/耐力/冷却离散分桶）。其余完全相同。</li><li><strong>测量</strong>：构造成对测试样本——同一初始画面、同一按键序列，但隐藏状态不同（耐力足够 vs 不足；Boss 处于可破防相位 vs 不可）。度量两件事：生成结果的<strong>裁定正确率</strong>（是否命中/是否被打断，用 demo 的规则引擎自动判定），以及<strong>后果出现时刻</strong>与规则定义时刻的帧差。</li><li><strong>判据</strong>：若 B 版裁定正确率显著高于 A 版，且 A 版在成对样本上呈现&quot;同输入同输出&quot;的塌缩（说明它只能按像素统计走），则支持论文判断。若两版差距落在噪声内，或 A 版在数据量增加时快速追上 B 版，则削弱它。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是指出论文的数据设计<strong>制造</strong>了它要论证的问题。具体做法：用同一段《黑神话：悟空》录像做两组采集，一组按作者做法禁用 UI 渲染 pass，另一组保留完整 HUD。然后训练同一个纯像素模型（不给任何显式状态），在两组数据上分别评测规则依赖交互的裁定正确率。</p><p>如果保留 HUD 的那组把差距抹平了大半，那么&quot;显式 state 是关键缺失物&quot;这个结论就有了替代解释：真正缺失的是<strong>状态的可观测性</strong>，而不是状态的显式表示。这对论文的实践指向影响很大——如果只要不遮 HUD 就够，那么昂贵的引擎打点、状态 schema 设计、跨游戏泛化问题就大部分不必要，工程重点应该转向&quot;让模型学会读画面里的仪表&quot;。</p><p>另一类可预测失效场景是跨游戏迁移。本文的状态 schema（血量、耐力、技能、装备、动画相位）是动作 RPG 特有的。策略游戏的状态是资源与科技树，赛车游戏是圈速与轮胎磨损。若显式状态方案要求每换一个游戏就重做一遍 schema 与打点，那么它相对于纯像素方案的可扩展性劣势会随游戏数量线性放大，这一点论文没有讨论。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>论文自己指出了一个几乎没人做的区分：control latency 要小，consequence latency 要<strong>准</strong>。现有全部加速工作都在优化前者，把后者当成同一类东西一起压缩。这里有一个非增量的重构机会。</p><p><strong>驱动局限</strong>：把后果延迟当成要最小化的量，等价于假设&quot;越快出现越好&quot;。但攻击的前摇、判定帧、后摇是游戏手感的一部分，效果提前出现读起来就是错的。目前后果出现的时刻完全交给生成先验，没有任何机制去对齐它与规则定义的时刻。</p><p><strong>可借鉴的相邻领域</strong>：语音与音乐生成里的<strong>时间对齐建模</strong>（强制对齐、duration predictor、时间标记条件），以及事件序列建模里的 <strong>temporal point process</strong>。这些工具专门处理&quot;事件应该在什么时刻发生&quot;，而不是&quot;事件内容是什么&quot;，正好与内容生成正交。</p><p><strong>新的 framing</strong>：把交互世界模型分解成两个头——一个内容头预测&quot;会发生什么&quot;，一个<strong>时序头</strong>预测&quot;在第几帧发生&quot;，后者以显式状态与动作相位为条件，用规则真值时刻直接监督。生成时把时序头的输出当作硬约束注入去噪过程（类似把 duration 作为条件的 TTS）。</p><p><strong>第一个实验</strong>：在本文的《黑神话：悟空》数据上，用引擎导出的动画相位与判定帧作为真值时刻标注，训练一个只预测&quot;命中判定发生在按键后第几帧&quot;的轻量时序头，评估它相对于&quot;从生成视频里事后检测判定时刻&quot;的误差分布。如果时序头能把误差压到几帧以内，而基线生成模型的判定时刻分布明显更宽更飘，那就说明后果时刻值得单独建模，而不是指望它从像素里涌现。</p>',50)])])}const u=a(p,[["render",l]]);export{g as __pageData,u as default};
